const prefillHospitalDocuments = `-- name: PrefillHospitalDocuments :many
SELECT title, document_date FROM ` + "`" + `record_documents` + "`" + `
WHERE user_id = ? AND kind = 'hospital' AND (document_date IS NULL OR document_date >= ?)
ORDER BY document_date
`

type PrefillHospitalDocumentsParams struct {
	UserID uint64
	Since  civildate.NullDate
}

type PrefillHospitalDocumentsRow struct {
	Title        sql.NullString
	DocumentDate civildate.NullDate
}

func (q *Queries) PrefillHospitalDocuments(ctx context.Context, arg PrefillHospitalDocumentsParams) ([]PrefillHospitalDocumentsRow, error) {
	rows, err := q.db.QueryContext(ctx, prefillHospitalDocuments, arg.UserID, arg.Since)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PrefillHospitalDocumentsRow{}
	for rows.Next() {
		var i PrefillHospitalDocumentsRow
		if err := rows.Scan(&i.Title, &i.DocumentDate); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

